/*
 * Splits the hero doodle for loading: the HTML carries only the lying pose with its first foot frame
 * (what the first paint shows); everything else (the other foot frames and the whole sitting pose)
 * goes to public/assets/hero/doodle-rest.json, which the page preloads at once and the hook mounts
 * into the SVG. Source: components/hero/heroDoodleFrames.ts (generated by gen-hero-doodle.py).
 *
 * Usage: node scripts/gen-hero-doodle-rest.mjs   (re-run whenever heroDoodleFrames.ts changes)
 */
import fs from "node:fs";

const src = fs.readFileSync("components/hero/heroDoodleFrames.ts", "utf8");
const pick = (name) => {
  const m = src.match(new RegExp(`export const ${name}\\b[^=]*= (.*);\\s*$`, "m"));
  if (!m) throw new Error(`${name} not found`);
  return JSON.parse(m[1]);
};
const rest = {
  foot: pick("FOOT_FRAMES").slice(1),
  sitting: pick("SITTING"),
  head: pick("HEAD_FRAMES"),
  blink: pick("BLINK_FRAMES"),
  type: pick("TYPE_FRAMES"),
};
fs.mkdirSync("public/assets/hero", { recursive: true });
fs.writeFileSync("public/assets/hero/doodle-rest.json", JSON.stringify(rest));
console.log("doodle-rest.json", fs.statSync("public/assets/hero/doodle-rest.json").size, "bytes");
